-- TestaCBT starter content: news, exam news, results, scholarships, blog articles, events and videos.
-- Generated by scripts/make-starter-sql.php. Safe to run more than once: rows that already exist are skipped.
-- Run it on the server with:  mysql -u YOUR_DB_USER -p YOUR_DB_NAME < database/starter-content.sql
-- Cover pictures load from Wikimedia Commons (free licences); the photo credit is at the bottom of each article.

SET NAMES utf8mb4;
SET @admin := (SELECT id FROM users WHERE role = 'admin' ORDER BY id LIMIT 1);
SET @exam_jamb := (SELECT id FROM exams WHERE slug = 'jamb');
SET @exam_waec := (SELECT id FROM exams WHERE slug = 'waec');
SET @exam_neco := (SELECT id FROM exams WHERE slug = 'neco');
SET @exam_igcse := (SELECT id FROM exams WHERE slug = 'igcse');
SET @exam_post_utme := (SELECT id FROM exams WHERE slug = 'post-utme');

